={{ JSON.stringify({
  parent: { database_id: $env.NOTION_EVAL_DB_ID },
  properties: {
    Name:        { title: [{ text: { content: $json.title.slice(0,200) } }] },
    Key:         { rich_text: [{ text: { content: $json.key } }] },
    Source:      { select: { name: $json.source || 'arXiv' } },
    Date:        $json.date ? { date: { start: $json.date } } : { date: null },
    Type:        { select: { name: $json.type } },
    Dimensions:  { multi_select: $json.dimensions.map(d => ({ name: d })) },
    'Proposed Dimension': { rich_text: $json.newDimension
        ? [{ text: { content: $json.newDimension.name + ' — ' + $json.newDimension.definition } }] : [] },
    Summary:     { rich_text: [{ text: { content: $json.oneLine.slice(0,1900) } }] },
    'Why it matters': { rich_text: [{ text: { content: $json.why.slice(0,1900) } }] },
    Confidence:  { number: $json.confidence },
    URL:         { url: $json.url || null },
    Status:      { select: { name: $json.newDimension ? 'proposed-dimension' : 'sent' } }
  }
}) }}

